import type { EventStream } from "./types"
import { Backoff } from "./backoff"

const QUIET_MS = 25_000

export interface StreamOptions {
  url: string
  backoff?: Backoff
  onEvent: (ty: string, payload: unknown) => void
}

export function watchdog(stream: EventStream, reconnect: () => void) {
  let timer = setTimeout(fire, QUIET_MS)
  function fire() {
    stream.close()
    reconnect()
  }
  const reset = () => {
    clearTimeout(timer)
    timer = setTimeout(fire, QUIET_MS)
  }
  stream.on("message", reset)
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") reset()
  })
  return () => clearTimeout(timer)
}

export function connectStream(opts: StreamOptions) {
  const backoff = opts.backoff ?? new Backoff({ base: 1_000, cap: 30_000 })
  let active: EventStream | undefined
  function open() {
    active?.close()
    const s = createEventStream(opts.url)
    active = s
    watchdog(s, () => setTimeout(open, backoff.fail()))
    s.on("message", (ev) => {
      backoff.message()
      opts.onEvent(ev.type, ev.data)
    })
  }
  open()
}

