const HEALTHY_MS = 60_000

export interface BackoffConfig {
  base: number
  cap: number
  clock?: () => number
}

export class Backoff {
  private attempts = 0
  private healthySince: number | null = null
  private readonly now: () => number

  constructor(private readonly cfg: BackoffConfig) {
    this.now = cfg.clock ?? Date.now
  }

  message() {
    const t = this.now()
    if (this.healthySince === null) {
      this.healthySince = t
      return
    }
    if (t - this.healthySince >= HEALTHY_MS) {
      this.attempts = 0
    }
  }

  fail(): number {
    this.healthySince = null
    const delay = Math.min(this.cfg.cap, this.cfg.base * 2 ** this.attempts)
    this.attempts += 1
    return delay
  }
}

