import type { SessionSummary } from "../types"

export function createSidebarStore() {
  let loaded = false
  const pending: Array<{ sessionID: string; title?: string }> = []
  const items = new Map<string, SessionSummary>()

  function applyUpdate(ev: { sessionID: string; title?: string }) {
    const cur = items.get(ev.sessionID)
    if (cur && ev.title) {
      items.set(ev.sessionID, { ...cur, title: ev.title })
    }
  }

  return {
    hydrate(list: SessionSummary[]) {
      for (const s of list) items.set(s.id, s)
      loaded = true
      for (const ev of pending.splice(0)) applyUpdate(ev)
    },
    onEvent(ty: string, ev: { sessionID: string; title?: string }) {
      if (ty === "session.updated" || ty === "session.renamed") {
        if (!loaded) pending.push(ev)
        else applyUpdate(ev)
      }
    },
  }
}

